INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1317681-ee411', 'stk-ee-220', 'EE 411', 'info', '{"desc": "السلام عليكم …\nياشباب السينيربروجكت حق الساينس 3 كريدتس و الابلايد نفس الكلام …\nلكن في الساينس في 6 ساعات لاب و ساعه ليكتشر بالاسبوع , وش نظامها هذي ؟ الطلاب يجتمعون لحالهم ولا يكون فيه دكتور باللاب ؟\nوهل مواضيع الساينس تختلف عن مواضيع الابلايد ؟\nمشكورين …واي معلومات عن اختيار فريق العمل و الدكتور و الامور هذي ؟\nوهل هو ينزل الترم الأول و الثاني ؟\nشكراً …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-411-senior-design-project/120706/2", "user": "EE-220", "ts": 1389261272000, "tid": 120706, "pn": 2}}', 1389261272000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1317910-ee411', 'stk-_prince', 'EE 411', 'info', '{"desc": "السلام عليكم …\n\nعليكم السلام\n\nياشباب السينيربروجكت حق الساينس 3 كريدتس و الابلايد نفس الكلام …\nلكن في الساينس في 6 ساعات لاب و ساعه ليكتشر بالاسبوع , وش نظامها هذي ؟ الطلاب يجتمعون لحالهم ولا يكون فيه دكتور باللاب ؟\n\nفي العادة القروب يحدد يوم للقاء الدكتور كل اسبوع ليتابع عملهم ويجاوب الاسئلة (مو شرط يكون نفس المسجل )\nوالباقي على القروب ينسقون مع بعضهم\n\nوهل مواضيع الساينس تختلف عن مواضيع الابلايد ؟\n\nنفس المواضيع تكون …طلاب الساينس يقدروا يصيروا مع الابلايد في قروب\n\nمشكورين …واي معلومات عن اختيار فريق العمل و الدكتور و الامور هذي ؟\n\nاختيار فريق العمل صراحة من قبل كان افضل ان كل قروب يقدموا اوراقهم سوا بعد معرفة بروجكت كل دكتور\nاما الحين فالوضع\"من سبق لبق\"الي يصيد السكشن يصير فيه\nيعني احتمال كبير انك ماتصير مع قروبك اللي متفق معاه اذا ماصدتوا نفس السكشن\n\nوهل هو ينزل الترم الأول و الثاني ؟\nشكراً …\n\nينزل الترمين 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-411-senior-design-project/120706/3", "user": "_PrInCe", "ts": 1389314545000, "tid": 120706, "pn": 3}}', 1389314545000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
